"use strict";

const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..");
const directory = path.join(root, "stories");
const stories = fs.readdirSync(directory)
  .filter(function (name) { return name.toLowerCase().endsWith(".json"); })
  .sort()
  .map(function (name) {
    return {
      fileName: name,
      definition: JSON.parse(fs.readFileSync(path.join(directory, name), "utf8"))
    };
  });

fs.writeFileSync(
  path.join(__dirname, "builtInStories.js"),
  "// Generated by node scripts\\bundleStories.js; edit stories/*.json instead.\n" +
    "window.builtInStories = " + JSON.stringify(stories, null, 2) + ";\n"
);
